 const social=document.createElement('section');social.id='companionSocial';social.hidden=true;social.dir='rtl';social.innerHTML='<header class="social-head"><button type="button" id="socialBack">← رجوع</button><strong>المجتمع والشات</strong><span id="socialSelfLabel">ملفي الشخصي</span></header><nav class="social-tabs"><button type="button" data-social-tab="community" class="active">🌐 المجتمع</button><button type="button" data-social-tab="friends">💬 محادثاتي</button><button type="button" data-social-tab="groups">👥 المجموعات</button><button type="button" data-social-tab="profile">👤 ملفي الشخصي</button></nav><div class="social-body"><section id="socialCommunity"><h3>المجتمع العام</h3><p class="social-hint">كل المستخدمين المسجلين يمكنهم رؤية الرسائل هنا.</p><div id="communityLog" class="social-log" aria-live="polite"></div><form id="communityForm" class="social-compose"><input id="communityInput" maxlength="1000" placeholder="اكتب رسالة للمجتمع…" required><button type="submit">إرسال</button></form><h3 class="social-section-gap">🏆 إنجازات الطلاب</h3><div id="achievementPostsLog" class="social-log"></div></section><section id="socialFriends" hidden><h3>الأشخاص الذين أضفتهم</h3><form id="addFriendForm" class="social-add"><input id="friendUsernameInput" maxlength="24" placeholder="اسم المستخدم (مثال: ahmed_23)" required><button type="submit">إضافة بالاسم</button></form><div id="socialFriendList" class="social-friend-list"></div><section id="directChatBox" hidden><div class="social-chat-title" id="directChatTitle"></div><div id="directChatLog" class="social-log"></div><form id="directChatForm" class="social-compose"><input id="directChatInput" maxlength="1000" placeholder="اكتب رسالتك الخاصة…" required><button type="submit">إرسال</button></form></section></section><section id="socialGroups" hidden><h3>المجموعات</h3><form id="createGroupForm" class="social-add"><input id="newGroupName" maxlength="60" placeholder="اسم المجموعة الجديدة" required><button type="submit">إنشاء مجموعة</button></form><div id="socialGroupList" class="social-friend-list"></div><section id="groupChatBox" hidden><div class="social-chat-title" id="groupChatTitle"></div><div id="groupChatLog" class="social-log"></div><form id="groupChatForm" class="social-compose"><input id="groupChatInput" maxlength="1000" placeholder="رسالة للمجموعة…" required><button type="submit">إرسال</button></form></section></section><section id="socialProfile" hidden><h3>ملفي الشخصي</h3><form id="socialProfileForm" class="social-profile-form"><label>اسم المستخدم الفريد<input id="socialProfileUsername" maxlength="24" pattern="[A-Za-z0-9_]{3,24}" required></label><label>الاسم الظاهر<input id="socialDisplayName" maxlength="40" required></label><label>الصورة الشخصية<input id="socialAvatarFile" type="file" accept="image/png,image/jpeg,image/webp"></label><img id="socialAvatarPreview" alt="معاينة الصورة الشخصية" hidden><button type="submit">حفظ الملف الشخصي</button></form><h3>نشر إنجاز</h3><form id="achievementPostForm" class="social-profile-form"><label>عنوان الإنجاز<input id="achievementTitle" maxlength="100" placeholder="مثال: أنهيت مراجعة التشريح" required></label><label>تفاصيل قصيرة<textarea id="achievementDescription" maxlength="500" placeholder="ما الذي أنجزته؟"></textarea></label><button type="submit">نشر الإنجاز للمجتمع</button></form><p id="socialStatus" role="status"></p><p class="social-hint">اسم المستخدم فريد ويُستخدم للعثور عليك وإضافتك. لا تشارك معلومات حساسة في المجتمع العام.</p></section></div>';
